const landingCss = "\n@font-face{\n  font-family:\"Sfizia\";\n  src:url(\"uploads/atipo-sfizia-regular.ttf\") format(\"truetype\");\n  font-weight:400;font-style:normal;font-display:swap;\n}\n@font-face{\n  font-family:\"Sfizia\";\n  src:url(\"uploads/atipo-sfizia-regular-italic.ttf\") format(\"truetype\");\n  font-weight:400;font-style:italic;font-display:swap;\n}\n:root{\n  --ink:#0e0e0c;\n  --ink-80:#0e0e0ccc;\n  --ink-60:#0e0e0c99;\n  --ink-40:#0e0e0c66;\n  --ink-15:#0e0e0c26;\n  --ink-08:#0e0e0c14;\n  --parchment:#f5f1e8;\n  --parchment-2:#efe9dc;\n  --paper:#fbf9f4;\n  --white:#ffffff;\n  --purple:#5150f7;\n  --purple-dark:#3d3cd4;\n  --purple-soft:#ecebff;\n  --rule:#d9d2c1;\n  --max:1400px;\n  --gutter:clamp(20px, 3vw, 40px);\n\n  --serif:\"Sfizia\", Cambria, Georgia, serif;\n  --sans:\"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Helvetica, Arial, sans-serif;\n  --mono:\"JetBrains Mono\", ui-monospace, SFMono-Regular, Menlo, monospace;\n}\n\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{\n  margin:0;\n  background:var(--parchment);\n  color:var(--ink);\n  font-family:var(--sans);\n  font-size:16px;\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  -moz-osx-font-smoothing:grayscale;\n  text-rendering:optimizeLegibility;\n}\nimg,svg{display:block;max-width:100%}\na{color:inherit;text-decoration:none}\n\n.container{max-width:var(--max);margin:0 auto;padding-inline:var(--gutter)}\n\n.eyebrow{\n  display:inline-flex;align-items:center;gap:10px;\n  font-family:var(--mono);\n  font-size:14px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--ink-60);\n}\n.eyebrow::before{\n  content:\"\";\n  width:16px;height:16px;\n  background-color:var(--purple);\n  -webkit-mask-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black'><rect x='10.6' y='2' width='2.8' height='20' rx='1.4'/><rect x='10.6' y='2' width='2.8' height='20' rx='1.4' transform='rotate(60 12 12)'/><rect x='10.6' y='2' width='2.8' height='20' rx='1.4' transform='rotate(120 12 12)'/></svg>\");\n          mask-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='black'><rect x='10.6' y='2' width='2.8' height='20' rx='1.4'/><rect x='10.6' y='2' width='2.8' height='20' rx='1.4' transform='rotate(60 12 12)'/><rect x='10.6' y='2' width='2.8' height='20' rx='1.4' transform='rotate(120 12 12)'/></svg>\");\n  -webkit-mask-size:contain;mask-size:contain;\n  -webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;\n  -webkit-mask-position:center;mask-position:center;\n  animation:eyebrow-spin 6s linear infinite;\n  flex:none;\n}\n@keyframes eyebrow-spin{\n  to{transform:rotate(360deg)}\n}\n@media(prefers-reduced-motion:reduce){\n  .eyebrow::before{animation:none}\n}\n\n.serif{font-family:var(--serif);font-weight:400;letter-spacing:-.01em;line-height:1.02}\n.italic{font-style:italic}\n\nh1,h2,h3,h4{margin:0;font-weight:400}\nh1.display{\n  font-family:var(--serif);\n  font-size:clamp(52px, 9vw, 128px);\n  line-height:.96;\n  letter-spacing:-.025em;\n}\nh2.display{\n  font-family:var(--serif);\n  font-size:clamp(40px, 5.5vw, 76px);\n  line-height:1;\n  letter-spacing:-.02em;\n}\nh3.display{font-family:var(--serif);font-size:clamp(28px, 2.6vw, 40px);line-height:1.05;letter-spacing:-.015em;}\n\n.lede{font-size:clamp(17px, 1.35vw, 20px);line-height:1.55;color:var(--ink-80);max-width:56ch}\n\n/* ==================== NAV ==================== */\n.nav{\n  position:sticky;top:0;z-index:50;\n  background:rgba(245,241,232,.85);\n  backdrop-filter:saturate(180%) blur(14px);\n  -webkit-backdrop-filter:saturate(180%) blur(14px);\n  border-bottom:1px solid transparent;\n  transition:border-color .2s;\n}\n.nav.scrolled{border-bottom-color:var(--ink-08)}\n.nav-inner{\n  display:flex;align-items:center;justify-content:space-between;\n  height:72px;\n}\n.brand{display:flex;align-items:center;gap:12px;font-family:var(--serif);font-size:22px;letter-spacing:-.01em;white-space:nowrap}\n.brand span{white-space:nowrap}\n.brand svg{width:30px;height:30px}\n.nav-links{display:flex;align-items:center;gap:6px}\n.nav-link{\n  padding:8px 14px;\n  font-size:16px;\n  color:var(--ink-80);\n  border-radius:999px;\n  transition:background .15s, color .15s;\n}\n.nav-link:hover{background:var(--ink-08);color:var(--ink)}\n.nav-cta{\n  display:inline-flex;align-items:center;gap:8px;\n  padding:10px 18px;\n  background:var(--ink);color:var(--paper);\n  border-radius:999px;\n  font-size:16px;font-weight:500;\n  transition:background .15s;\n}\n.nav-cta:hover{background:var(--purple)}\n.nav-cta svg{width:14px;height:14px}\n@media(max-width:780px){\n  .nav-links .nav-link:not(.cta-wrap){display:none}\n}\n\n/* ==================== HERO ==================== */\n.hero{padding:clamp(32px, 6vw, 80px) 0 clamp(40px, 7vw, 100px);position:relative;isolation:isolate}\n.hero-canvas{\n  position:absolute;inset:0;width:100%;height:100%;\n  z-index:-1;\n  pointer-events:none;\n  opacity:1;\n  mask-image:radial-gradient(ellipse 120% 100% at 50% 55%, #000 75%, transparent 100%);\n  -webkit-mask-image:radial-gradient(ellipse 120% 100% at 50% 55%, #000 75%, transparent 100%);\n}\n@media(prefers-reduced-motion:reduce){.hero-canvas{display:none}}\n.hero-top{\n  display:flex;justify-content:space-between;align-items:baseline;\n  margin-bottom:clamp(28px, 5vw, 56px);\n  gap:16px 28px;flex-wrap:wrap;\n}\n.hero-meta{\n  display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;\n  font-family:var(--mono);font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-60);\n}\n.hero-meta b{color:var(--ink);font-weight:500}\n.hero-meta .sep{color:var(--ink-40)}\n\n.hero h1 .bracket{color:var(--ink-40);font-style:italic}\n.hero h1 .ampersand{color:var(--purple);font-style:italic}\n.hero h1 .under{\n  background-image:linear-gradient(var(--ink),var(--ink));\n  background-size:100% 2px;background-position:0 100%;background-repeat:no-repeat;\n  padding-bottom:6px;\n}\n\n.hero-grid{\n  display:grid;\n  grid-template-columns:1.4fr 1fr;\n  gap:clamp(24px, 4vw, 64px);\n  align-items:end;\n  margin-top:clamp(32px, 5vw, 56px);\n}\n@media(max-width:880px){.hero-grid{grid-template-columns:1fr}}\n\n.hero-right{display:flex;flex-direction:column;gap:24px}\n.hero-right .lede{max-width:none}\n\n.ctas{display:flex;flex-wrap:wrap;gap:12px;align-items:center}\n.btn-primary{\n  display:inline-flex;align-items:center;gap:10px;\n  padding:16px 26px;\n  background:var(--ink);color:var(--paper);\n  border-radius:999px;\n  font-size:15px;font-weight:500;\n  transition:background .2s, transform .2s;\n}\n.btn-primary:hover{background:var(--purple);transform:translateY(-1px)}\n.btn-primary svg{width:14px;height:14px;transition:transform .2s}\n.btn-primary:hover svg{transform:translate(3px,-3px)}\n.btn-secondary{\n  display:inline-flex;align-items:center;gap:10px;\n  padding:16px 26px;\n  border:1px solid var(--ink-15);\n  border-radius:999px;\n  font-size:15px;font-weight:500;color:var(--ink);\n  transition:border-color .2s,background .2s;\n}\n.btn-secondary:hover{border-color:var(--ink);background:var(--white)}\n\n.trust-row{\n  display:flex;align-items:center;gap:14px;\n  padding:14px 0;\n  border-top:1px solid var(--rule);\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-60);\n}\n.stars{display:inline-flex;gap:2px;color:var(--purple)}\n.stars svg{width:14px;height:14px}\n\n/* UK flag chip (abstract, not literal) */\n.uk-chip{\n  display:inline-flex;align-items:center;gap:8px;\n  padding:6px 10px 6px 6px;\n  background:var(--white);\n  border:1px solid var(--ink-15);\n  border-radius:999px;\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;\n}\n.uk-chip .flag{\n  width:18px;height:18px;border-radius:50%;\n  background:\n    linear-gradient(45deg, transparent 45%, #fff 45%, #fff 55%, transparent 55%),\n    linear-gradient(-45deg, transparent 45%, #fff 45%, #fff 55%, transparent 55%),\n    linear-gradient(0deg, transparent 47%, #fff 47%, #fff 53%, transparent 53%),\n    linear-gradient(90deg, transparent 47%, #fff 47%, #fff 53%, transparent 53%),\n    #c8102e;\n}\n\n/* ==================== MARQUEE / TRUST STRIP ==================== */\n.strip{\n  background:var(--ink);color:var(--paper);\n  padding:26px 0;\n  overflow:hidden;\n  border-top:1px solid var(--ink-15);\n}\n.strip-track{\n  display:flex;gap:64px;\n  animation:scroll 40s linear infinite;\n  width:max-content;\n}\n.strip-item{\n  display:inline-flex;align-items:center;gap:14px;\n  font-family:var(--serif);font-size:28px;letter-spacing:-.01em;white-space:nowrap;\n}\n.strip-item .dot{width:7px;height:7px;background:var(--purple);border-radius:50%;flex:none}\n.strip-item .dot--x{\n  background:transparent;\n  position:relative;width:14px;height:14px;\n}\n.strip-item .dot--x::before,.strip-item .dot--x::after{\n  content:\"\";position:absolute;inset:0;\n  background:var(--paper);\n}\n.strip-item .dot--x::before{clip-path:polygon(0 45%,100% 45%,100% 55%,0 55%)}\n.strip-item .dot--x::after{clip-path:polygon(45% 0,55% 0,55% 100%,45% 100%);transform:rotate(45deg)}\n\n@keyframes scroll{\n  from{transform:translateX(0)}\n  to{transform:translateX(-50%)}\n}\n\n/* ==================== VALUE / WHY ==================== */\n.section{padding:clamp(60px,8vw,120px) 0}\n.section--paper{background:var(--paper)}\n.section--ink{background:var(--ink);color:var(--paper)}\n.section--ink .eyebrow{color:rgba(255,255,255,.6)}\n.section--ink .eyebrow::before{background-color:#fff}\n\n.section-head{\n  display:grid;grid-template-columns:1fr 1.4fr;gap:clamp(24px,4vw,80px);\n  align-items:end;\n  margin-bottom:clamp(40px,5vw,72px);\n}\n@media(max-width:780px){.section-head{grid-template-columns:1fr}}\n.section-head .lede{color:var(--ink-60)}\n.section--ink .section-head .lede{color:rgba(255,255,255,.72)}\n\n/* ---- WHY / VALUES grid lines ---- */\n.section--values{position:relative;overflow-x:clip;--pb:clamp(60px,8vw,120px)}\n.pillars{\n  display:grid;grid-template-columns:repeat(3,1fr);\n  position:relative;z-index:0;\n}\n/* full-bleed horizontal rule \u2014 edge to edge of the screen */\n.pillars::before{\n  content:\"\";position:absolute;top:0;left:50%;transform:translateX(-50%);\n  width:100vw;height:1px;background:var(--rule);\n}\n/* two vertical dividers, dropped over the section's bottom padding */\n.pillars::after{\n  content:\"\";position:absolute;z-index:-1;\n  top:0;left:0;right:0;bottom:calc(-1 * var(--pb));\n  background:\n    linear-gradient(var(--rule),var(--rule)) 33.333% 0/1px 100% no-repeat,\n    linear-gradient(var(--rule),var(--rule)) 66.667% 0/1px 100% no-repeat;\n  pointer-events:none;\n}\n.pillars article{\n  padding:36px 24px 36px 0;\n  position:relative;\n}\n.pillars article:nth-child(n+2){padding-left:28px}\n.pillar-num{\n  font-family:var(--mono);font-size:14px;letter-spacing:.18em;color:var(--ink-40);\n  text-transform:uppercase;\n  margin-bottom:28px;\n}\n.pillar-title{font-family:var(--serif);font-size:28px;line-height:1.08;letter-spacing:-.01em;margin-bottom:14px}\n.pillar-body{font-size:16px;line-height:1.6;color:var(--ink-80)}\n.pillar-tag{\n  display:inline-block;margin-top:18px;\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;\n  color:var(--purple);\n}\n@media(max-width:780px){\n  .pillars{grid-template-columns:1fr}\n  .pillars::after{display:none}\n  .pillars article{border-bottom:1px solid var(--rule);padding-left:0!important;padding-right:0}\n  .pillars article:last-child{border-bottom:none}\n}\n\n/* ==================== PROCESS ==================== */\n.section--paper#process{position:relative;isolation:isolate}\n.process-canvas{\n  position:absolute;inset:0;width:100%;height:100%;\n  z-index:0;pointer-events:none;\n  opacity:.85;\n  mask-image:radial-gradient(ellipse 110% 100% at 50% 50%, #000 65%, transparent 100%);\n  -webkit-mask-image:radial-gradient(ellipse 110% 100% at 50% 50%, #000 65%, transparent 100%);\n}\n.section--paper#process > .container{position:relative;z-index:1}\n@media(prefers-reduced-motion:reduce){.process-canvas{display:none}}\n\n.process-grid{\n  display:grid;grid-template-columns:repeat(4,1fr);gap:16px;\n}\n.step{\n  background:var(--white);\n  border:1px solid var(--ink-08);\n  border-radius:20px;\n  padding:28px 24px;\n  position:relative;\n  min-height:280px;\n  display:flex;flex-direction:column;justify-content:space-between;\n}\n.step-num{\n  font-family:var(--serif);font-size:64px;line-height:1;color:var(--purple);letter-spacing:-.02em;\n}\n.step-num .small{font-family:var(--mono);font-size:14px;color:var(--ink-40);letter-spacing:.14em;margin-left:4px;vertical-align:top}\n.step h4{font-family:var(--serif);font-size:24px;line-height:1.1;margin:18px 0 10px;font-weight:400}\n.step p{font-size:16px;color:var(--ink-60);line-height:1.6;margin:0}\n.step-meta{\n  margin-top:20px;padding-top:14px;border-top:1px dashed var(--ink-15);\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-60);\n}\n@media(max-width:880px){.process-grid{grid-template-columns:repeat(2,1fr)}}\n@media(max-width:520px){.process-grid{grid-template-columns:1fr}}\n\n/* ==================== WORK GRID ==================== */\n.work-grid{\n  display:grid;grid-template-columns:repeat(12,1fr);gap:16px;\n}\n.work{\n  border-radius:20px;overflow:hidden;position:relative;\n  background:var(--parchment-2);\n  aspect-ratio:4/3;\n  display:flex;align-items:center;justify-content:center;\n  transition:transform .3s;\n}\n.work:hover{transform:translateY(-4px)}\n.work-mark{\n  font-family:var(--serif);font-size:clamp(48px,7vw,96px);color:var(--ink);letter-spacing:-.02em;\n}\n.work--tall{aspect-ratio:3/4}\n.work--wide{aspect-ratio:16/9}\n.work-meta{\n  position:absolute;bottom:16px;left:16px;right:16px;\n  display:flex;justify-content:space-between;align-items:end;\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-60);\n}\n.work-meta .tag{background:rgba(255,255,255,.8);padding:4px 8px;border-radius:4px}\n\n.work-a{grid-column:span 5;background:#e8e3d5}\n.work-b{grid-column:span 4;background:#dcd4bf}\n.work-c{grid-column:span 3;background:var(--ink);color:var(--paper)}\n.work-c .work-mark{color:var(--paper)}\n.work-d{grid-column:span 3;background:#e6dcc6}\n.work-e{grid-column:span 6;background:var(--purple);color:var(--paper)}\n.work-e .work-mark{color:var(--paper)}\n.work-f{grid-column:span 3;background:#f0e8d2}\n@media(max-width:780px){\n  .work-grid>*{grid-column:span 6!important;aspect-ratio:1/1!important}\n}\n@media(max-width:520px){\n  .work-grid>*{grid-column:span 12!important}\n}\n\n/* ==================== PACKAGES ==================== */\n.packages-head{text-align:center;margin-bottom:clamp(40px,5vw,72px)}\n.packages-head h2{margin:16px auto 20px;max-width:22ch}\n.packages-head .lede{margin:0 auto;color:var(--ink-60)}\n\n.packages{\n  display:grid;grid-template-columns:repeat(3,1fr);gap:16px;\n  align-items:stretch;\n}\n@media(max-width:880px){.packages{grid-template-columns:1fr}}\n\n.pkg{\n  background:var(--paper);\n  border:1px solid var(--ink-08);\n  border-radius:24px;\n  padding:32px 28px;\n  display:flex;flex-direction:column;\n  position:relative;\n  transition:border-color .2s, transform .2s;\n}\n.pkg:hover{border-color:var(--ink-15)}\n.pkg--featured{\n  background:var(--ink);color:var(--paper);\n  border:1px solid var(--ink);\n  transform:scale(1.01);\n}\n.pkg--featured:hover{transform:scale(1.01) translateY(-3px)}\n\n.pkg-ribbon{\n  position:absolute;top:-12px;left:50%;transform:translateX(-50%);\n  background:var(--purple);color:#fff;\n  padding:6px 12px;border-radius:999px;\n  font-family:var(--mono);font-size:14px;letter-spacing:.16em;text-transform:uppercase;\n  white-space:nowrap;\n}\n.pkg-name{\n  font-family:var(--mono);font-size:14px;letter-spacing:.2em;text-transform:uppercase;\n  color:var(--ink-60);\n}\n.pkg--featured .pkg-name{color:rgba(255,255,255,.6)}\n\n.pkg-tagline{\n  font-family:var(--serif);font-size:22px;line-height:1.1;margin:8px 0 20px;letter-spacing:-.01em;\n}\n\n.pkg-price{\n  display:flex;align-items:baseline;gap:6px;\n  font-family:var(--serif);\n  margin-bottom:8px;\n}\n.pkg-price .amt{font-size:64px;line-height:1;letter-spacing:-.03em}\n.pkg-price .sym{font-size:32px;color:var(--ink-40)}\n.pkg--featured .pkg-price .sym{color:rgba(255,255,255,.5)}\n.pkg-price .note{font-family:var(--sans);font-size:13px;color:var(--ink-60);margin-left:6px}\n.pkg--featured .pkg-price .note{color:rgba(255,255,255,.6)}\n\n.pkg-vat{\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;\n  color:var(--ink-40);margin-bottom:24px;\n}\n.pkg--featured .pkg-vat{color:rgba(255,255,255,.5)}\n\n.pkg-list{list-style:none;padding:0;margin:0 0 28px;border-top:1px solid var(--ink-08)}\n.pkg--featured .pkg-list{border-top-color:rgba(255,255,255,.12)}\n.pkg-list li{\n  display:flex;align-items:flex-start;gap:12px;\n  padding:14px 0;\n  border-bottom:1px solid var(--ink-08);\n  font-size:16px;line-height:1.55;\n}\n.pkg--featured .pkg-list li{border-bottom-color:rgba(255,255,255,.12)}\n.pkg-list li svg{flex:none;width:16px;height:16px;margin-top:3px;color:var(--purple)}\n.pkg--featured .pkg-list li svg{color:#a5a4ff}\n.pkg-list .primary{font-weight:500}\n\n.pkg-cta{\n  display:flex;align-items:center;justify-content:center;gap:10px;\n  padding:14px 20px;\n  border-radius:999px;\n  background:var(--ink);color:var(--paper);\n  font-size:14px;font-weight:500;\n  margin-top:auto;\n  transition:background .2s,transform .2s;\n}\n.pkg-cta:hover{background:var(--purple);transform:translateY(-1px)}\n.pkg-cta--invert{background:var(--paper);color:var(--ink)}\n.pkg-cta--invert:hover{background:var(--purple);color:var(--paper)}\n.pkg-cta svg{width:14px;height:14px;transition:transform .2s}\n.pkg-cta:hover svg{transform:translateX(3px)}\n\n.pkg-footnote{\n  margin-top:12px;text-align:center;\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-40);\n}\n.pkg--featured .pkg-footnote{color:rgba(255,255,255,.5)}\n\n/* ==================== TESTIMONIALS ==================== */\n.testimonial-grid{\n  display:grid;grid-template-columns:repeat(3,1fr);gap:16px;\n}\n@media(max-width:880px){.testimonial-grid{grid-template-columns:1fr}}\n.tstm{\n  background:var(--paper);border:1px solid var(--ink-08);border-radius:20px;\n  padding:28px;display:flex;flex-direction:column;gap:20px;\n}\n.tstm blockquote{\n  margin:0;\n  font-family:var(--sans);\n  font-size:18px;\n  line-height:1.5;\n  letter-spacing:-.005em;\n  color:var(--ink);\n  font-weight:400;\n}\n.tstm-attr{\n  display:flex;align-items:center;gap:12px;margin-top:auto;\n}\n.tstm-avatar{\n  width:40px;height:40px;border-radius:50%;\n  background:var(--purple-soft);color:var(--purple);\n  display:grid;place-items:center;\n  font-family:var(--sans);font-size:14px;font-weight:600;letter-spacing:.02em;\n  flex:none;\n}\n.tstm-name{font-size:16px;font-weight:500}\n.tstm-role{font-size:13px;color:var(--ink-60)}\n.tstm-sector{\n  display:inline-flex;align-items:center;gap:6px;\n  font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-60);\n  padding:4px 10px;border:1px solid var(--ink-08);border-radius:999px;align-self:flex-start;\n}\n.tstm-sector::before{content:\"\";width:6px;height:6px;border-radius:50%;background:var(--purple)}\n\n/* ==================== ABOUT / CREDENTIALS ==================== */\n.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(32px,5vw,80px);align-items:center}\n@media(max-width:880px){.about-grid{grid-template-columns:1fr}}\n.about-card{\n  background:var(--white);border-radius:24px;padding:36px;border:1px solid var(--ink-08);\n}\n.stat-row{display:grid;grid-template-columns:repeat(2,1fr);gap:32px 40px;margin-top:32px;padding-top:32px;border-top:1px solid var(--ink-08)}\n.stat .num{font-family:var(--serif);font-size:clamp(56px, 5.5vw, 88px);line-height:1;letter-spacing:-.03em;color:var(--ink)}\n.stat .lbl{font-family:var(--mono);font-size:14px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-60);margin-top:12px;display:block}\n.signature{\n  font-family:var(--sans);\n  font-size:14px;\n  font-weight:500;\n  letter-spacing:.04em;\n  color:var(--ink-60);\n  margin-top:32px;\n}\n\n/* ==================== FAQ ==================== */\n.faq-grid{display:grid;grid-template-columns:1fr 2fr;gap:clamp(24px,4vw,80px);align-items:flex-start}\n@media(max-width:880px){.faq-grid{grid-template-columns:1fr}}\n.faq-side{position:sticky;top:96px;align-self:start}\n@media(max-width:880px){.faq-side{position:static;top:auto}}\n.faq-list{border-top:1px solid var(--ink-15)}\ndetails.faq{\n  border-bottom:1px solid var(--ink-15);\n  padding:22px 0;\n}\ndetails.faq summary{\n  list-style:none;\n  display:flex;justify-content:space-between;align-items:flex-start;gap:20px;\n  cursor:pointer;\n  font-family:var(--serif);\n  font-size:clamp(22px,2vw,28px);line-height:1.15;letter-spacing:-.01em;\n  color:var(--ink);\n}\ndetails.faq summary::-webkit-details-marker{display:none}\n.faq-toggle{\n  flex:none;width:34px;height:34px;border-radius:50%;\n  border:1px solid var(--ink-15);\n  display:grid;place-items:center;\n  transition:transform .25s, background .25s, color .25s;\n  color:var(--ink-60);\n}\ndetails.faq[open] .faq-toggle{transform:rotate(45deg);background:var(--purple);color:#fff;border-color:var(--purple)}\n.faq-toggle svg{width:14px;height:14px}\ndetails.faq p{\n  margin:14px 0 0;\n  font-size:17px;line-height:1.65;color:var(--ink-80);\n  max-width:70ch;\n}\ndetails.faq .faq-q-num{\n  font-family:var(--mono);font-size:14px;letter-spacing:.18em;color:var(--ink-40);\n  margin-bottom:6px;\n}\n\n/* ==================== FINAL CTA ==================== */\n.final{\n  background:var(--purple);color:#fff;\n  border-radius:32px;\n  padding:clamp(48px,7vw,96px) clamp(28px,5vw,72px);\n  margin:0 var(--gutter);\n  position:relative;overflow:hidden;\n}\n.final-inner{max-width:var(--max);margin:0 auto;position:relative;z-index:2}\n.final-canvas{\n  position:absolute;inset:0;width:100%;height:100%;\n  z-index:0;\n  pointer-events:none;\n  mask-image:radial-gradient(ellipse 130% 110% at 50% 50%, #000 78%, transparent 100%);\n  -webkit-mask-image:radial-gradient(ellipse 130% 110% at 50% 50%, #000 78%, transparent 100%);\n}\n@media(prefers-reduced-motion:reduce){.final-canvas{display:none}}\n.final::before{\n  content:\"\";position:absolute;inset:0;\n  background:\n    radial-gradient(ellipse at 20% 120%, rgba(255,255,255,.25), transparent 50%),\n    radial-gradient(ellipse at 100% 0%, rgba(0,0,0,.25), transparent 50%);\n  pointer-events:none;\n  z-index:1;\n}\n.final h2{margin-bottom:24px;max-width:20ch}\n.final .lede{color:rgba(255,255,255,.82);max-width:60ch}\n.final .ctas{margin-top:36px}\n.final .btn-primary{background:#fff;color:var(--ink)}\n.final .btn-primary:hover{background:var(--ink);color:#fff}\n.final .btn-secondary{border-color:rgba(255,255,255,.35);color:#fff}\n.final .btn-secondary:hover{background:rgba(255,255,255,.12);border-color:#fff}\n\n/* Pretitle mark \u2014 purple disappears on the purple CTA, so use white */\n.final .eyebrow::before{\n  background-color:#fff;\n  box-shadow:none;\n  animation:eyebrow-spin 6s linear infinite;\n}\n@media(prefers-reduced-motion:reduce){\n  .final .eyebrow::before{animation:none}\n}\n\n.final-stamp{\n  position:absolute;bottom:48px;right:48px;\n  width:184px;height:184px;\n  display:grid;place-items:center;\n  color:#fff;\n  pointer-events:none;\n}\n.final-stamp::before{\n  content:\"\";position:absolute;inset:0;border-radius:50%;\n  border:1.5px solid rgba(255,255,255,.4);\n}\n.stamp-rotor{\n  position:absolute;inset:0;width:100%;height:100%;\n  animation:stamp-spin 38s linear infinite;\n}\n.stamp-text{\n  font-family:var(--mono);\n  font-size:11px;\n  letter-spacing:.22em;\n  text-transform:uppercase;\n  fill:#fff;\n  fill-opacity:1;\n  font-weight:500;\n}\n.stamp-mark{\n  position:relative;z-index:1;\n  width:54px;height:auto;\n  color:#fff;\n  opacity:1;\n  display:block;\n}\n@keyframes stamp-spin{to{transform:rotate(360deg)}}\n@media(prefers-reduced-motion:reduce){.stamp-rotor{animation:none}}\n@media(max-width:680px){.final-stamp{display:none}}\n@media(max-width:960px){.final-stamp{width:152px;height:152px;bottom:32px;right:32px}.stamp-mark{width:44px}.stamp-text{font-size:9.5px;letter-spacing:.2em}}\n\n/* ==================== FOOTER ==================== */\nfooter{background:var(--ink);color:var(--paper);padding:80px 0 32px;margin-top:80px}\n.foot-top{\n  display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:40px;\n  padding-bottom:56px;border-bottom:1px solid rgba(255,255,255,.1);\n}\n@media(max-width:780px){.foot-top{grid-template-columns:1fr 1fr}}\n.foot-brand{display:flex;flex-direction:column;gap:20px;max-width:360px}\n.foot-brand .brand{color:var(--paper)}\n.foot-brand .brand svg path{fill:var(--paper)}\n.foot-brand p{color:rgba(255,255,255,.65);font-size:16px;line-height:1.6;margin:0}\n.foot-col h5{\n  font-family:var(--mono);font-size:14px;letter-spacing:.18em;text-transform:uppercase;\n  color:rgba(255,255,255,.5);\n  margin:0 0 18px;font-weight:500;\n}\n.foot-col ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:10px}\n.foot-col a{font-size:16px;color:rgba(255,255,255,.8);transition:color .15s}\n.foot-col a:hover{color:var(--purple-soft)}\n\n.foot-bottom{\n  display:flex;justify-content:space-between;align-items:center;gap:20px;\n  padding-top:32px;\n  font-family:var(--mono);font-size:14px;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.5);\n  flex-wrap:wrap;\n}\n\n/* Big wordmark */\n.big-mark{\n  font-family:var(--serif);font-size:clamp(80px,22vw,300px);\n  line-height:.8;letter-spacing:-.04em;color:var(--ink);\n  padding-bottom:0;\n  margin-top:60px;\n  text-align:center;\n  opacity:.07;\n  user-select:none;\n}\n.big-mark--foot{color:var(--paper);opacity:.04;margin-top:60px;margin-bottom:-80px}\n\n";
const landingHtml = "<!-- ================ NAV ================ -->\n<header class=\"nav\" id=\"nav\">\n  <div class=\"container nav-inner\">\n    <a href=\"#\" class=\"brand\" aria-label=\"Logo Fountain home\">\n      <svg viewBox=\"0 0 410 386\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M156.71 386H0V242.918C70.3986 266.077 127.467 318.602 156.71 386Z\" fill=\"currentColor\"/><path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M410 386H249.29C279.086 317.33 337.766 264.1 410 241.638V386Z\" fill=\"currentColor\"/><path d=\"M410 15.0303V185.937C324.315 202.111 252.229 256.772 212.392 331.271C212.12 331.78 211.849 332.29 211.581 332.8C208.522 338.604 205.659 344.527 203 350.56C200.341 344.527 197.478 338.604 194.419 332.8C194.151 332.29 193.88 331.78 193.608 331.271C154.392 257.934 83.9262 203.821 0 186.722V17.2785C99.657 74.0035 174.135 169.951 202.485 284.147C202.658 284.846 202.83 285.545 203 286.246C203.17 285.545 203.342 284.846 203.515 284.147C232.243 168.428 308.337 71.4479 410 15.0303Z\" fill=\"currentColor\"/><path d=\"M255 50.5C255 78.3904 232.39 101 204.5 101C176.61 101 154 78.3904 154 50.5C154 22.6096 176.61 0 204.5 0C232.39 0 255 22.6096 255 50.5Z\" fill=\"currentColor\"/></svg>\n      <span>Logo Fountain</span>\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a class=\"nav-link\" href=\"#work\">Work</a>\n      <a class=\"nav-link\" href=\"#process\">Process</a>\n      <a class=\"nav-link\" href=\"#packages\">Packages</a>\n      <a class=\"nav-link\" href=\"#about\">About</a>\n      <a class=\"nav-link\" href=\"#faq\">FAQ</a>\n      <a class=\"nav-cta\" href=\"#packages\">\n        Book your logo\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 17L17 7M17 7H8M17 7V16\"/></svg>\n      </a>\n    </nav>\n  </div>\n</header>\n\n<!-- ================ HERO ================ -->\n<section class=\"hero\">\n  <canvas class=\"hero-canvas\" id=\"heroCanvas\" aria-hidden=\"true\"></canvas>\n  <div class=\"container\">\n\n    <div class=\"hero-top\">\n      <div class=\"eyebrow\">Est. 2018 \u00b7 A studio in the United Kingdom</div>\n      <div class=\"hero-meta\">\n        <span><b>127</b> marks delivered</span>\n        <span class=\"sep\">\u00b7</span>\n        <span><b>10\u201314 days</b> typical turnaround</span>\n      </div>\n    </div>\n\n    <h1 class=\"display\">\n      Logos designed <span class=\"italic\" style=\"color:var(--ink-60)\">in</span> Britain.<br>\n      By <span class=\"italic\">people</span>, <span class=\"ampersand\">&amp;</span> never<br>\n      by prompts.\n    </h1>\n\n    <div class=\"hero-grid\">\n      <div>\n        <div class=\"trust-row\" style=\"margin-top:40px\">\n          <span class=\"stars\" aria-label=\"4.9 out of 5\">\n            <svg viewBox=\"0 0 20 20\" fill=\"currentColor\"><path d=\"M10 1l2.6 5.6 6.1.9-4.4 4.3 1 6.1L10 15l-5.4 2.9 1-6.1L1.3 7.5l6.1-.9z\"/></svg>\n            <svg viewBox=\"0 0 20 20\" fill=\"currentColor\"><path d=\"M10 1l2.6 5.6 6.1.9-4.4 4.3 1 6.1L10 15l-5.4 2.9 1-6.1L1.3 7.5l6.1-.9z\"/></svg>\n            <svg viewBox=\"0 0 20 20\" fill=\"currentColor\"><path d=\"M10 1l2.6 5.6 6.1.9-4.4 4.3 1 6.1L10 15l-5.4 2.9 1-6.1L1.3 7.5l6.1-.9z\"/></svg>\n            <svg viewBox=\"0 0 20 20\" fill=\"currentColor\"><path d=\"M10 1l2.6 5.6 6.1.9-4.4 4.3 1 6.1L10 15l-5.4 2.9 1-6.1L1.3 7.5l6.1-.9z\"/></svg>\n            <svg viewBox=\"0 0 20 20\" fill=\"currentColor\"><path d=\"M10 1l2.6 5.6 6.1.9-4.4 4.3 1 6.1L10 15l-5.4 2.9 1-6.1L1.3 7.5l6.1-.9z\"/></svg>\n          </span>\n          <span>4.9/5 \u00b7 127 verified reviews</span>\n        </div>\n      </div>\n      <div class=\"hero-right\">\n        <p class=\"lede\">\n          <strong>Logo Fountain</strong> is a small studio of British designers building distinctive identities for independent businesses across the UK. Every mark is sketched, drawn and refined by a named designer \u2014 no AI tools, no stock templates, no work sent overseas.\n        </p>\n        <div class=\"ctas\">\n          <a href=\"#packages\" class=\"btn-primary\">\n            View packages\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 17L17 7M17 7H8M17 7V16\"/></svg>\n          </a>\n          <a href=\"#work\" class=\"btn-secondary\">See recent work</a>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<!-- ================ TRUST STRIP ================ -->\n<div class=\"strip\" aria-label=\"Values\">\n  <div class=\"strip-track\">\n    <!-- duplicated for seamless loop -->\n    <span class=\"strip-item\"><span class=\"dot\"></span>Drawn by hand in the UK</span>\n    <span class=\"strip-item\"><span class=\"dot--x\"></span>No generative AI</span>\n    <span class=\"strip-item\"><span class=\"dot\"></span>No outsourcing</span>\n    <span class=\"strip-item\"><span class=\"dot--x\"></span>No templates</span>\n    <span class=\"strip-item\"><span class=\"dot\"></span>Named designer on every project</span>\n    <span class=\"strip-item\"><span class=\"dot--x\"></span>Full ownership &amp; copyright transferred</span>\n\n    <span class=\"strip-item\" aria-hidden=\"true\"><span class=\"dot\"></span>Drawn by hand in the UK</span>\n    <span class=\"strip-item\" aria-hidden=\"true\"><span class=\"dot--x\"></span>No generative AI</span>\n    <span class=\"strip-item\" aria-hidden=\"true\"><span class=\"dot\"></span>No outsourcing</span>\n    <span class=\"strip-item\" aria-hidden=\"true\"><span class=\"dot--x\"></span>No templates</span>\n    <span class=\"strip-item\" aria-hidden=\"true\"><span class=\"dot\"></span>Named designer on every project</span>\n    <span class=\"strip-item\" aria-hidden=\"true\"><span class=\"dot--x\"></span>Full ownership &amp; copyright transferred</span>\n  </div>\n</div>\n\n<section class=\"section section--values\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <div>\n        <div class=\"eyebrow\">Why British designers</div>\n        <h2 class=\"display\" style=\"margin-top:18px\">A quieter kind <span class=\"italic\" style=\"color:var(--purple)\">of craft.</span></h2>\n      </div>\n      <p class=\"lede\">\n        The market is flooded with generated marks and templated lookalikes. We build the opposite \u2014 identities made slowly, by hand, by people who live and work in the country you trade in. Your brand is one of the few assets nobody else can buy. Treat it accordingly.\n      </p>\n    </div>\n\n    <div class=\"pillars\">\n      <article>\n        <div class=\"pillar-num\">01 \u2014 Human craft</div>\n        <h3 class=\"pillar-title\">Drawn, not generated.</h3>\n        <p class=\"pillar-body\">Every concept begins with pencil sketches from a senior designer in our UK studio. We do not use Midjourney, DALL\u00b7E, Stable Diffusion or any generative tool at any stage of the process. Ever.</p>\n        <span class=\"pillar-tag\">Zero AI policy</span>\n      </article>\n      <article>\n        <div class=\"pillar-num\">02 \u2014 British studio</div>\n        <h3 class=\"pillar-title\">All work stays in the UK.</h3>\n        <p class=\"pillar-body\">No offshoring, no white-label agencies, no freelance bidding sites. The designer you brief is the designer who draws your mark \u2014 and you'll know them by name from day one.</p>\n        <span class=\"pillar-tag\">UK-based team</span>\n      </article>\n      <article>\n        <div class=\"pillar-num\">03 \u2014 Built to last</div>\n        <h3 class=\"pillar-title\">Marks that age well.</h3>\n        <p class=\"pillar-body\">We design for the decade, not the trend cycle. Every logo is tested at scale \u2014 from a 16px favicon to a shop front \u2014 and delivered with full guidelines so your identity stays consistent as you grow.</p>\n        <span class=\"pillar-tag\">Timeless by default</span>\n      </article>\n    </div>\n  </div>\n</section>\n\n<!-- ================ PROCESS ================ -->\n<section class=\"section section--paper\" id=\"process\">\n  <canvas class=\"process-canvas\" id=\"processCanvas\" aria-hidden=\"true\"></canvas>\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <div>\n        <div class=\"eyebrow\">The process</div>\n        <h2 class=\"display\" style=\"margin-top:18px\">Four steps. <span class=\"italic\" style=\"color:var(--purple)\">No surprises.</span></h2>\n      </div>\n      <p class=\"lede\">\n        A tight, predictable path from first brief to final delivery. You'll always know where your project sits, what happens next, and who is working on it. Most identities land in <strong>10\u201314 working days</strong>.\n      </p>\n    </div>\n\n    <div class=\"process-grid\">\n      <div class=\"step\">\n        <div>\n          <div class=\"step-num\">01<span class=\"small\">/04</span></div>\n          <h4>Brief &amp; discovery</h4>\n          <p>A structured questionnaire covering your audience, competitors, tone and where your mark needs to live. We ask in plain English \u2014 no jargon, no fluff.</p>\n        </div>\n        <div class=\"step-meta\">Day 1 \u00b7 ~30 mins</div>\n      </div>\n      <div class=\"step\">\n        <div>\n          <div class=\"step-num\">02<span class=\"small\">/04</span></div>\n          <h4>Sketch &amp; concept</h4>\n          <p>Your named designer sketches by hand, then refines 1\u20135 directions in the studio. Each concept comes with a written rationale explaining the thinking.</p>\n        </div>\n        <div class=\"step-meta\">Day 2\u20137 \u00b7 Drawn in-house</div>\n      </div>\n      <div class=\"step\">\n        <div>\n          <div class=\"step-num\">03<span class=\"small\">/04</span></div>\n          <h4>Refine &amp; review</h4>\n          <p>You review concepts through your private portal, leave pinpoint feedback, and we refine to a single final mark. Everything is tracked \u2014 no lost email threads.</p>\n        </div>\n        <div class=\"step-meta\">Day 8\u201312 \u00b7 1\u20133 rounds</div>\n      </div>\n      <div class=\"step\">\n        <div>\n          <div class=\"step-num\">04<span class=\"small\">/04</span></div>\n          <h4>Deliver &amp; handover</h4>\n          <p>Final artwork supplied as vector and raster files, plus a usage guide. Full copyright is transferred \u2014 the mark is legally, unambiguously yours.</p>\n        </div>\n        <div class=\"step-meta\">Day 13\u201314 \u00b7 Full ownership</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================ WORK ================ -->\n<section class=\"section\" id=\"work\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <div>\n        <div class=\"eyebrow\">Recent work</div>\n        <h2 class=\"display\" style=\"margin-top:18px\">Marks we've drawn <span class=\"italic\" style=\"color:var(--purple)\">this year.</span></h2>\n      </div>\n      <p class=\"lede\">\n        A small selection of identities delivered to UK founders, independents and family businesses. Each was drawn in our studio, owned outright by the client, and built to last.\n      </p>\n    </div>\n\n    <div class=\"work-grid\">\n      <article class=\"work work-a\" aria-label=\"Alderman &amp; Co \u2014 solicitors, Bath\">\n        <span class=\"work-mark\">A&amp;Co</span>\n        <div class=\"work-meta\"><span>Alderman &amp; Co \u00b7 Bath</span><span class=\"tag\">Solicitors</span></div>\n      </article>\n      <article class=\"work work-b\" aria-label=\"Kelpie \u2014 coastal caf\u00e9, Whitstable\">\n        <span class=\"work-mark italic\">Kelpie</span>\n        <div class=\"work-meta\"><span>Kelpie \u00b7 Whitstable</span><span class=\"tag\">Hospitality</span></div>\n      </article>\n      <article class=\"work work-c\" aria-label=\"Forth \u2014 engineering, Edinburgh\">\n        <span class=\"work-mark\">Forth.</span>\n        <div class=\"work-meta\" style=\"color:rgba(255,255,255,.6)\"><span>Forth \u00b7 Edinburgh</span><span class=\"tag\" style=\"background:rgba(255,255,255,.12);color:#fff\">Engineering</span></div>\n      </article>\n      <article class=\"work work-d\" aria-label=\"Nimbus \u2014 insurance, Manchester\">\n        <span class=\"work-mark\">N</span>\n        <div class=\"work-meta\"><span>Nimbus \u00b7 Manchester</span><span class=\"tag\">Insurance</span></div>\n      </article>\n      <article class=\"work work-e\" aria-label=\"Wren Bakery \u2014 artisan bakery, Bristol\">\n        <span class=\"work-mark italic\">Wren.</span>\n        <div class=\"work-meta\" style=\"color:rgba(255,255,255,.8)\"><span>Wren Bakery \u00b7 Bristol</span><span class=\"tag\" style=\"background:rgba(255,255,255,.15);color:#fff\">Food &amp; drink</span></div>\n      </article>\n      <article class=\"work work-f\" aria-label=\"Hedge Row \u2014 garden design, Cotswolds\">\n        <span class=\"work-mark\">H/R</span>\n        <div class=\"work-meta\"><span>Hedge Row \u00b7 Cotswolds</span><span class=\"tag\">Landscape</span></div>\n      </article>\n    </div>\n  </div>\n</section>\n\n<!-- ================ PACKAGES \u2014 THE MAIN EVENT ================ -->\n<section class=\"section section--paper\" id=\"packages\">\n  <div class=\"container\">\n    <div class=\"packages-head\">\n      <div class=\"eyebrow\" style=\"justify-content:center\">Packages</div>\n      <h2 class=\"display\">Three clear packages.<br><span class=\"italic\" style=\"color:var(--purple)\">Fixed prices. Full ownership.</span></h2>\n      <p class=\"lede\">All packages include a named British designer, full copyright transfer, and every file you'll need to launch. Secure checkout is handled by Stripe.</p>\n    </div>\n\n    <div class=\"packages\">\n      <!-- ESSENTIAL -->\n      <article class=\"pkg\">\n        <div class=\"pkg-name\">01 \u00b7 Essential</div>\n        <p class=\"pkg-tagline\">For sole traders &amp; first-year founders finding their feet.</p>\n        <div class=\"pkg-price\">\n          <span class=\"sym\">\u00a3</span><span class=\"amt\">299</span>\n          <span class=\"note\">one-off</span>\n        </div>\n        <div class=\"pkg-vat\">one-off \u00b7 secure Stripe checkout</div>\n\n        <ul class=\"pkg-list\">\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg><span class=\"primary\">2 strategic concept directions</span></li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>2 rounds of refinements</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Primary logo + favicon</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Vector &amp; raster file pack</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Full copyright transferred</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>~10 working days</li>\n        </ul>\n\n        <a href=\"#packages\" data-package=\"essential\" class=\"pkg-cta\">\n          Choose Essential\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14M13 5l7 7-7 7\"/></svg>\n        </a>\n        <div class=\"pkg-footnote\">Best for single-founder start-ups</div>\n      </article>\n\n      <!-- PROFESSIONAL (featured) -->\n      <article class=\"pkg pkg--featured\">\n        <span class=\"pkg-ribbon\">Most popular</span>\n        <div class=\"pkg-name\">02 \u00b7 Professional</div>\n        <p class=\"pkg-tagline\">For growing UK businesses ready to look like a serious brand.</p>\n        <div class=\"pkg-price\">\n          <span class=\"sym\">\u00a3</span><span class=\"amt\">499</span>\n          <span class=\"note\">one-off</span>\n        </div>\n        <div class=\"pkg-vat\">one-off \u00b7 secure Stripe checkout</div>\n\n        <ul class=\"pkg-list\">\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg><span class=\"primary\">3 distinct concept directions</span></li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>2 rounds of refinements</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Primary + secondary lockups, monogram, favicon</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Colour system + typography pairing</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>8-page usage guide (PDF)</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Full copyright transferred</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>~14 working days</li>\n        </ul>\n\n        <a href=\"#packages\" data-package=\"professional\" class=\"pkg-cta pkg-cta--invert\">\n          Choose Professional\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14M13 5l7 7-7 7\"/></svg>\n        </a>\n        <div class=\"pkg-footnote\">The sweet spot for most UK SMEs</div>\n      </article>\n\n      <!-- COMPLETE -->\n      <article class=\"pkg\">\n        <div class=\"pkg-name\">03 \u00b7 Complete</div>\n        <p class=\"pkg-tagline\">For established firms launching, rebranding or going public.</p>\n        <div class=\"pkg-price\">\n          <span class=\"sym\">\u00a3</span><span class=\"amt\">749</span>\n          <span class=\"note\">one-off</span>\n        </div>\n        <div class=\"pkg-vat\">one-off \u00b7 secure Stripe checkout</div>\n\n        <ul class=\"pkg-list\">\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg><span class=\"primary\">3 concept directions + strategic rationale</span></li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>5 rounds of refinements</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Full mark suite: primary, secondary, icon, wordmark, responsive</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Colour, type &amp; motion guidelines (24 pages)</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Business card, letterhead &amp; signage templates</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Priority turnaround \u00b7 2 design calls included</li>\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>Full copyright transferred</li>\n        </ul>\n\n        <a href=\"#packages\" data-package=\"complete\" class=\"pkg-cta\">\n          Choose Complete\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12h14M13 5l7 7-7 7\"/></svg>\n        </a>\n        <div class=\"pkg-footnote\">For rebrands &amp; serious launches</div>\n      </article>\n    </div>\n\n    <p style=\"text-align:center;margin-top:40px;color:var(--ink-60);font-size:16px\">\n      Not sure which to pick? <a href=\"#faq\" style=\"color:var(--purple);text-decoration:underline;text-underline-offset:3px\">Read the FAQ</a> \u00b7 All packages include a 7-day money-back guarantee if we don't show initial concepts on time.\n    </p>\n  </div>\n</section>\n\n<!-- ================ TESTIMONIALS ================ -->\n<section class=\"section\">\n  <div class=\"container\">\n    <div class=\"section-head\">\n      <div>\n        <div class=\"eyebrow\">What clients say</div>\n        <h2 class=\"display\" style=\"margin-top:18px\">Real businesses.<br><span class=\"italic\" style=\"color:var(--purple)\">Real British high streets.</span></h2>\n      </div>\n      <p class=\"lede\">\n        A handful of the 127 studios, shops, practices and start-ups we've worked with since 2018. Every review collected through verified channels \u2014 no incentives, no cherry-picking.\n      </p>\n    </div>\n\n    <div class=\"testimonial-grid\">\n      <div class=\"tstm\">\n        <span class=\"tstm-sector\">Hospitality \u00b7 Yorkshire</span>\n        <blockquote>\u201cIt felt like working with an old friend who happened to be brilliant at drawing. Our tea shop has people photographing the shopfront every Saturday \u2014 <em>that's</em> the mark doing its job.\u201d</blockquote>\n        <div class=\"tstm-attr\">\n          <div class=\"tstm-avatar\">EH</div>\n          <div>\n            <div class=\"tstm-name\">Eleanor Hartley</div>\n            <div class=\"tstm-role\">Owner, Hartley's Tea Rooms \u00b7 Harrogate</div>\n          </div>\n        </div>\n      </div>\n      <div class=\"tstm\">\n        <span class=\"tstm-sector\">Professional services</span>\n        <blockquote>\u201cWe wouldn't dream of using an AI-generated logo for a law firm. Logo Fountain understood that instantly.\u201d</blockquote>\n        <div class=\"tstm-attr\">\n          <div class=\"tstm-avatar\">JM</div>\n          <div>\n            <div class=\"tstm-name\">James Montgomery</div>\n            <div class=\"tstm-role\">Partner, Montgomery &amp; Finch \u00b7 London</div>\n          </div>\n        </div>\n      </div>\n      <div class=\"tstm\">\n        <span class=\"tstm-sector\">Retail \u00b7 Scotland</span>\n        <blockquote>\u201cProperly thoughtful. The designer rang me after seeing my shop on Google Street View \u2014 that's the level of care.\u201d</blockquote>\n        <div class=\"tstm-attr\">\n          <div class=\"tstm-avatar\">RA</div>\n          <div>\n            <div class=\"tstm-name\">Rhona Abernethy</div>\n            <div class=\"tstm-role\">Founder, The Fiddlehead \u00b7 Inverness</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================ ABOUT / CREDENTIALS ================ -->\n<section class=\"section section--paper\" id=\"about\">\n  <div class=\"container\">\n    <div class=\"about-grid\">\n      <div>\n        <div class=\"eyebrow\">The studio</div>\n        <h2 class=\"display\" style=\"margin-top:18px;margin-bottom:24px\">A studio of four, <span class=\"italic\" style=\"color:var(--purple)\">not forty.</span></h2>\n        <p class=\"lede\" style=\"margin-bottom:20px\">\n          We're a team of four senior British designers working from a small studio above a caf\u00e9 in Bristol. We keep the team small on purpose \u2014 it's the only way to guarantee every project gets the designer you hired, and the care you're paying for.\n        </p>\n        <p class=\"lede\">\n          Between us: 47 years at agencies including Pentagram, DesignStudio and SomeOne; work for the V&amp;A, John Lewis, Channel 4 and dozens of independent UK businesses; a stubborn refusal to use AI tools for any part of the creative process.\n        </p>\n        <div class=\"signature\">\u2014 The Logo Fountain team</div>\n      </div>\n      <div class=\"about-card\">\n        <div class=\"eyebrow\">By the numbers</div>\n        <h3 class=\"serif\" style=\"font-size:30px;margin:16px 0 8px\">Eight years. One country. No shortcuts.</h3>\n        <p style=\"color:var(--ink-60);font-size:16px;margin:0\">A transparent look at the studio since we opened in 2018.</p>\n\n        <div class=\"stat-row\">\n          <div class=\"stat\"><span class=\"num\">127</span><span class=\"lbl\">UK brands identified</span></div>\n          <div class=\"stat\"><span class=\"num\">4.9</span><span class=\"lbl\">Avg. review score</span></div>\n          <div class=\"stat\"><span class=\"num\">98%</span><span class=\"lbl\">On-time delivery</span></div>\n          <div class=\"stat\"><span class=\"num\">\u00a30</span><span class=\"lbl\">Spent on AI tools</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================ FAQ ================ -->\n<section class=\"section\" id=\"faq\">\n  <div class=\"container\">\n    <div class=\"faq-grid\">\n      <div class=\"faq-side\">\n        <div class=\"eyebrow\">FAQ</div>\n        <h2 class=\"display\" style=\"margin-top:18px;margin-bottom:20px\">Answered <span class=\"italic\" style=\"color:var(--purple)\">honestly.</span></h2>\n        <p style=\"color:var(--ink-60);max-width:36ch;font-size:16px;line-height:1.6\">\n          The questions we're asked most often by UK businesses considering a new logo. Still unsure? <a href=\"mailto:hello@logofountain.co.uk\" style=\"color:var(--ink);text-decoration:underline;text-underline-offset:3px\">Email the studio directly</a>.\n        </p>\n      </div>\n      <div class=\"faq-list\">\n        <details class=\"faq\" open>\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.01</div>\n              <span>Are all your designers actually based in the UK?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>Yes \u2014 every designer on the team is UK-based and UK-employed. We don't use overseas contractors, offshore freelance platforms or agency sub-contractors. We can share full designer profiles (with working addresses in Bristol, Manchester and Edinburgh) before you buy if that's helpful.</p>\n        </details>\n\n        <details class=\"faq\">\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.02</div>\n              <span>Do you really not use any AI tools?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>No generative AI is used at any stage \u2014 not for concept generation, not for colour palettes, not for mood-boarding, not for type exploration. Our concept development begins with pencil on paper. It's in our contract, and we're happy to sign an explicit non-AI clause for clients in regulated industries (legal, financial, healthcare) where this matters.</p>\n        </details>\n\n        <details class=\"faq\">\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.03</div>\n              <span>How much does a logo cost in the UK?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>Hand-drawn logo design from a UK-based studio typically ranges from \u00a3400 for a sole-trader mark up to \u00a315,000+ for a large brand system. Our three packages \u2014 Essential (\u00a3299), Professional (\u00a3499) and Complete (\u00a3749) \u2014 sit at the accessible end of the market without cutting corners on craft. Current package prices are Essential (\u00a3299), Professional (\u00a3499) and Complete (\u00a3749), with secure Stripe checkout and full copyright transfer included.</p>\n        </details>\n\n        <details class=\"faq\">\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.04</div>\n              <span>Who owns the copyright to my finished logo?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>You do \u2014 in full, without restriction, worldwide. On final delivery we transfer copyright to your limited company or sole-trader name via a signed deed of assignment, consistent with UK copyright law. You can register the mark as a UK or EU trademark without needing further permission from us.</p>\n        </details>\n\n        <details class=\"faq\">\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.05</div>\n              <span>How long does the whole process take?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>Roughly 10 working days for Essential, 14 for Professional, and 18\u201321 for Complete. Rush turnaround is available as a \u00a3195 add-on at checkout if you need a mark in under a week \u2014 we don't charge for rush unless we can genuinely commit to it.</p>\n        </details>\n\n        <details class=\"faq\">\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.06</div>\n              <span>Can you register the trademark for us?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>We don't file trademarks directly, but we'll supply the exact artwork and specifications required by the UKIPO and recommend a trusted UK trademark attorney we've worked alongside for years. A standard UK word-and-logo filing is typically \u00a3170\u2013\u00a3400 plus solicitor fees.</p>\n        </details>\n\n        <details class=\"faq\">\n          <summary>\n            <div>\n              <div class=\"faq-q-num\">Q.07</div>\n              <span>What if I don't like any of the concepts?</span>\n            </div>\n            <span class=\"faq-toggle\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg></span>\n          </summary>\n          <p>It's rare \u2014 but if initial concepts don't land, we'll happily produce a second round at no extra cost before refinement rounds begin. Professional and Complete packages include a free re-brief call with the designer. If after all that you genuinely aren't happy, we offer a 50% refund on Essential and Professional packages within 14 days.</p>\n        </details>\n      </div>\n    </div>\n  </div>\n\n</section>\n\n<!-- ================ FINAL CTA ================ -->\n<div class=\"final\" role=\"complementary\">\n  <canvas class=\"final-canvas\" id=\"finalCanvas\" aria-hidden=\"true\"></canvas>\n  <div class=\"final-inner\">\n    <div class=\"eyebrow\" style=\"color:rgba(255,255,255,.7)\">Take the first step</div>\n    <h2 class=\"display\" style=\"margin-top:18px;color:#fff\">Let's draw something <span class=\"italic\">worth keeping.</span></h2>\n    <p class=\"lede\">\n      Tell us about your business in a five-minute brief. A named British designer will reply within one working day with honest thoughts, a realistic timeline, and the right package for where you are.\n    </p>\n    <div class=\"ctas\">\n      <a href=\"#packages\" class=\"btn-primary\">\n        Start your brief\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 17L17 7M17 7H8M17 7V16\"/></svg>\n      </a>\n      <a href=\"mailto:hello@logofountain.co.uk\" class=\"btn-secondary\">Email the studio</a>\n    </div>\n  </div>\n  <div class=\"final-stamp\" aria-hidden=\"true\">\n    <svg viewBox=\"0 0 200 200\" class=\"stamp-rotor\">\n      <defs>\n        <path id=\"stampCircle\" d=\"M 100,100 m -78,0 a 78,78 0 1,1 156,0 a 78,78 0 1,1 -156,0\"/>\n      </defs>\n      <text class=\"stamp-text\">\n        <textPath href=\"#stampCircle\" startOffset=\"0\">Made in the UK \u2022 No AI, no outsourcing \u2022 Drawn by hand \u2022 Est. 2018 \u2022 </textPath>\n      </text>\n    </svg>\n    <svg viewBox=\"0 0 410 386\" class=\"stamp-mark\" aria-hidden=\"true\">\n      <g fill=\"currentColor\">\n        <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M156.71 386H0V242.918C70.3986 266.077 127.467 318.602 156.71 386Z\"/>\n        <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M410 386H249.29C279.086 317.33 337.766 264.1 410 241.638V386Z\"/>\n        <path d=\"M410 15.0303V185.937C324.315 202.111 252.229 256.772 212.392 331.271C212.12 331.78 211.849 332.29 211.581 332.8C208.522 338.604 205.659 344.527 203 350.56C200.341 344.527 197.478 338.604 194.419 332.8C194.151 332.29 193.88 331.78 193.608 331.271C154.392 257.934 83.9262 203.821 0 186.722V17.2785C99.657 74.0035 174.135 169.951 202.485 284.147C202.658 284.846 202.83 285.545 203 286.246C203.17 285.545 203.342 284.846 203.515 284.147C232.243 168.428 308.337 71.4479 410 15.0303Z\"/>\n        <path d=\"M255 50.5C255 78.3904 232.39 101 204.5 101C176.61 101 154 78.3904 154 50.5C154 22.6096 176.61 0 204.5 0C232.39 0 255 22.6096 255 50.5Z\"/>\n      </g>\n    </svg>\n  </div>\n</div>\n\n<!-- ================ FOOTER ================ -->\n<footer>\n  <div class=\"container\">\n    <div class=\"foot-top\">\n      <div class=\"foot-brand\">\n        <div class=\"brand\" style=\"color:var(--paper)\">\n          <svg viewBox=\"0 0 410 386\" aria-hidden=\"true\" style=\"width:22px;height:22px\"><path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M156.71 386H0V242.918C70.3986 266.077 127.467 318.602 156.71 386Z\" fill=\"currentColor\"/><path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M410 386H249.29C279.086 317.33 337.766 264.1 410 241.638V386Z\" fill=\"currentColor\"/><path d=\"M410 15.0303V185.937C324.315 202.111 252.229 256.772 212.392 331.271C212.12 331.78 211.849 332.29 211.581 332.8C208.522 338.604 205.659 344.527 203 350.56C200.341 344.527 197.478 338.604 194.419 332.8C194.151 332.29 193.88 331.78 193.608 331.271C154.392 257.934 83.9262 203.821 0 186.722V17.2785C99.657 74.0035 174.135 169.951 202.485 284.147C202.658 284.846 202.83 285.545 203 286.246C203.17 285.545 203.342 284.846 203.515 284.147C232.243 168.428 308.337 71.4479 410 15.0303Z\" fill=\"currentColor\"/><path d=\"M255 50.5C255 78.3904 232.39 101 204.5 101C176.61 101 154 78.3904 154 50.5C154 22.6096 176.61 0 204.5 0C232.39 0 255 22.6096 255 50.5Z\" fill=\"currentColor\"/></svg>\n          <span>Logo Fountain</span>\n        </div>\n        <p>Bespoke logo design by British designers. Made by hand, in the UK, for independent businesses who'd rather not look like everyone else.</p>\n        <p style=\"font-family:var(--mono);font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.5)\">Studio \u00b7 Bristol, Gloucestershire &amp; Edinburgh</p>\n      </div>\n      <div class=\"foot-col\">\n        <h5>Studio</h5>\n        <ul>\n          <li><a href=\"#about\">About</a></li>\n          <li><a href=\"#work\">Recent work</a></li>\n          <li><a href=\"#process\">Our process</a></li>\n          <li><a href=\"/journal\">Journal</a></li>\n        </ul>\n      </div>\n      <div class=\"foot-col\">\n        <h5>Packages</h5>\n        <ul>\n          <li><a href=\"#packages\">Essential \u00b7 \u00a3299</a></li>\n          <li><a href=\"#packages\">Professional \u00b7 \u00a3499</a></li>\n          <li><a href=\"#packages\">Complete \u00b7 \u00a3749</a></li>\n          <li><a href=\"#faq\">Package FAQ</a></li>\n        </ul>\n      </div>\n      <div class=\"foot-col\">\n        <h5>Contact</h5>\n        <ul>\n          <li><a href=\"mailto:hello@logofountain.co.uk\">hello@logofountain.co.uk</a></li>\n          <li><a href=\"tel:+441179000000\">+44 117 900 0000</a></li>\n          <li><a href=\"/login\">Client login</a></li>\n          <li><a href=\"#packages\">Start a brief</a></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"foot-bottom\">\n      <span>\u00a9 2018\u20132026 Logo Fountain Ltd \u00b7 Company details pending</span>\n      <span>Registered in England &amp; Wales</span>\n    </div>\n  </div>\n  <div class=\"big-mark big-mark--foot\" aria-hidden=\"true\">Logo <em class=\"italic\">Fountain</em></div>\n</footer>";
const rippleScript = "\n  // subtle nav border on scroll\n  const nav = document.getElementById('nav');\n  window.addEventListener('scroll', () => {\n    nav.classList.toggle('scrolled', window.scrollY > 8);\n  }, {passive:true});\n\n  // close other FAQs when one opens (accordion behaviour)\n  document.querySelectorAll('details.faq').forEach(d => {\n    d.addEventListener('toggle', () => {\n      if (d.open) {\n        document.querySelectorAll('details.faq').forEach(other => {\n          if (other !== d) other.open = false;\n        });\n      }\n    });\n  });\n\n  // ==================== FLUID RIPPLES (reusable) ====================\n  // A genuine 2D wave-equation simulation on a low-resolution height-field.\n  // Each cell stores water height; every frame we propagate the wave to\n  // neighbours and apply damping, exactly like the classic Hugo Elias\n  // water effect. The result is rendered into ImageData using a base\n  // colour modulated by the surface gradient (peaks lighter, troughs\n  // darker \u2014 true refraction shading, not drawn rings).\n  // Drops happen occasionally and on click, sending real waves across\n  // the surface that bounce, interfere, and decay naturally.\n  function mountFluidRipples(canvas, opts){\n    if (!canvas) return;\n    opts = opts || {};\n    const BASE_R = opts.baseR ?? 245;\n    const BASE_G = opts.baseG ?? 241;\n    const BASE_B = opts.baseB ?? 232;\n    // Tonal response per gradient unit. Auto-pick a sensible default\n    // based on whether the base colour is dark or light so the ripples\n    // stay visible on either.\n    const luma = 0.299 * BASE_R + 0.587 * BASE_G + 0.114 * BASE_B;\n    const SHADE = opts.shade ?? (luma < 128 ? 0.10 : 0.06);\n    const AUTO_DROP_MIN = opts.autoDropMin ?? 2400;\n    const AUTO_DROP_RANGE = opts.autoDropRange ?? 3200;\n    const HOVER_POKE = opts.hoverPoke ?? 90;\n    const CLICK_POKE = opts.clickPoke ?? 1400;\n    const AUTO_POKE_MIN = opts.autoPokeMin ?? 700;\n    const AUTO_POKE_RANGE = opts.autoPokeRange ?? 600;\n\n    const ctx = canvas.getContext('2d', {willReadFrequently: true});\n    // Pixel-art smoothing off so upscale stays crisp-ish (browser still\n    // bilinear-filters the drawImage step, which we want for softness).\n    ctx.imageSmoothingEnabled = true;\n    ctx.imageSmoothingQuality = 'high';\n\n    // Low-res simulation grid \u2014 high enough for nice waves, low enough\n    // that we can run a full 2D propagation every frame at 60fps.\n    const GRID_W = opts.gridW ?? 220;\n    const GRID_H = opts.gridH ?? 140;\n\n    // Two height buffers (ping-pong). Values are roughly in [-2048, 2048].\n    let cur  = new Int16Array(GRID_W * GRID_H);\n    let prev = new Int16Array(GRID_W * GRID_H);\n\n    const sim = document.createElement('canvas');\n    sim.width = GRID_W;\n    sim.height = GRID_H;\n    const sctx = sim.getContext('2d');\n    const imgData = sctx.createImageData(GRID_W, GRID_H);\n\n    let W = 0, H = 0, DPR = Math.min(window.devicePixelRatio || 1, 2);\n\n    function resize(){\n      const rect = canvas.getBoundingClientRect();\n      W = rect.width; H = rect.height;\n      canvas.width = W * DPR;\n      canvas.height = H * DPR;\n      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n    }\n\n    // Inject energy at (gx,gy) \u2014 a \"drop\" of given strength\n    function poke(gx, gy, strength){\n      gx = gx | 0; gy = gy | 0;\n      if (gx < 2 || gx > GRID_W - 3 || gy < 2 || gy > GRID_H - 3) return;\n      // Soft drop: a small Gaussian-ish dot rather than a single pixel,\n      // so the leading wavefront is smooth instead of pixelated.\n      const radius = 3;\n      for (let dy = -radius; dy <= radius; dy++){\n        for (let dx = -radius; dx <= radius; dx++){\n          const d2 = dx*dx + dy*dy;\n          if (d2 > radius*radius) continue;\n          const falloff = 1 - Math.sqrt(d2) / (radius + 1);\n          prev[(gy + dy) * GRID_W + (gx + dx)] += (strength * falloff) | 0;\n        }\n      }\n    }\n\n    // One wave-equation step.\n    // new = (left + right + up + down) / 2 - prev,  then * damping\n    // This is the standard 2D wave-equation FD scheme.\n    function step(){\n      const w = GRID_W, h = GRID_H;\n      // Damping: 1 = no decay; <1 = waves lose energy. 0.985 = lazy fade.\n      // Implemented as multiply-then-shift to stay fast.\n      // We do `new = ((sum)>>1) - prev` then `new -= new>>6` (\u2248 *0.984)\n      for (let y = 1; y < h - 1; y++){\n        const row = y * w;\n        const rowU = row - w;\n        const rowD = row + w;\n        for (let x = 1; x < w - 1; x++){\n          const i = row + x;\n          const sum = cur[i - 1] + cur[i + 1] + cur[rowU + x] + cur[rowD + x];\n          let v = (sum >> 1) - prev[i];\n          v -= v >> 6; // damping\n          prev[i] = v;\n        }\n      }\n      // Swap buffers\n      const tmp = cur; cur = prev; prev = tmp;\n    }\n\n    // Render the height-field into ImageData using the base tone.\n    // Shading: for each cell, sample the X gradient (height diff with\n    // left neighbour). A positive gradient \u2192 highlight (lighter); negative\n    // \u2192 shadow (darker). This is the cheap-but-convincing refraction look.\n    function render(){\n      const data = imgData.data;\n      const w = GRID_W, h = GRID_H;\n      for (let y = 0; y < h; y++){\n        const row = y * w;\n        for (let x = 0; x < w; x++){\n          const i = row + x;\n          // X-gradient from neighbour to the left (clamped at edges)\n          const xl = x > 0 ? cur[i - 1] : cur[i];\n          const grad = cur[i] - xl;\n          // Map gradient \u2192 tonal offset\n          const t = grad * SHADE;\n          let r = BASE_R + t;\n          let g = BASE_G + t * 0.95;\n          let b = BASE_B + t * 0.8;\n          if (r < 0) r = 0; else if (r > 255) r = 255;\n          if (g < 0) g = 0; else if (g > 255) g = 255;\n          if (b < 0) b = 0; else if (b > 255) b = 255;\n          const p = i << 2;\n          data[p]   = r;\n          data[p+1] = g;\n          data[p+2] = b;\n          data[p+3] = 255;\n        }\n      }\n      sctx.putImageData(imgData, 0, 0);\n      // Upscale onto the visible canvas \u2014 bilinear filtering provides the\n      // soft \"real water\" look.\n      ctx.clearRect(0, 0, W, H);\n      ctx.drawImage(sim, 0, 0, W, H);\n    }\n\n    // Spawn an automatic drop occasionally\n    let nextDropAt = performance.now() + 800;\n    function maybeAutoDrop(now){\n      if (now >= nextDropAt){\n        const gx = (0.08 + Math.random() * 0.84) * GRID_W;\n        const gy = (0.10 + Math.random() * 0.80) * GRID_H;\n        poke(gx, gy, AUTO_POKE_MIN + (Math.random() * AUTO_POKE_RANGE | 0));\n        nextDropAt = now + AUTO_DROP_MIN + Math.random() * AUTO_DROP_RANGE;\n      }\n    }\n\n    function frame(now){\n      maybeAutoDrop(now);\n      step();\n      render();\n      rafId = requestAnimationFrame(frame);\n    }\n\n    let rafId = 0;\n    let running = false;\n    function start(){\n      if (running) return;\n      running = true;\n      rafId = requestAnimationFrame(frame);\n    }\n    function stop(){\n      running = false;\n      if (rafId) cancelAnimationFrame(rafId);\n      rafId = 0;\n    }\n\n    // Pause when offscreen \u2014 keeps cost zero on canvases the user can't see\n    if ('IntersectionObserver' in window){\n      const io = new IntersectionObserver((entries) => {\n        for (const e of entries){\n          if (e.isIntersecting) start(); else stop();\n        }\n      }, {rootMargin: '120px'});\n      io.observe(canvas);\n    } else {\n      start();\n    }\n\n    let resizeTimer;\n    window.addEventListener('resize', () => {\n      clearTimeout(resizeTimer);\n      resizeTimer = setTimeout(resize, 100);\n    });\n\n    // Click anywhere to drop a ripple\n    canvas.parentElement.addEventListener('click', (e) => {\n      const rect = canvas.getBoundingClientRect();\n      const gx = ((e.clientX - rect.left) / rect.width) * GRID_W;\n      const gy = ((e.clientY - rect.top)  / rect.height) * GRID_H;\n      poke(gx, gy, CLICK_POKE);\n    }, {passive: true});\n\n    // Subtle ripples follow the cursor (very small pokes) so the surface\n    // feels alive when the user moves the mouse.\n    let lastMove = 0;\n    canvas.parentElement.addEventListener('mousemove', (e) => {\n      const now = performance.now();\n      if (now - lastMove < 90) return; // throttle\n      lastMove = now;\n      const rect = canvas.getBoundingClientRect();\n      const gx = ((e.clientX - rect.left) / rect.width) * GRID_W;\n      const gy = ((e.clientY - rect.top)  / rect.height) * GRID_H;\n      poke(gx, gy, HOVER_POKE);\n    }, {passive: true});\n\n    resize();\n    // Seed two initial drops so the surface is moving on load\n    poke(GRID_W * 0.30, GRID_H * 0.40, 1100);\n    setTimeout(() => poke(GRID_W * 0.72, GRID_H * 0.62, 900), 700);\n  }\n\n  // Mount on the hero (parchment surface)\n  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches){\n    mountFluidRipples(document.getElementById('heroCanvas'), {\n      baseR: 245, baseG: 241, baseB: 232,\n    });\n    // Process section \u2014 gentler version on the lighter paper background\n    mountFluidRipples(document.getElementById('processCanvas'), {\n      baseR: 251, baseG: 249, baseB: 244,\n      shade: 0.05,\n      autoDropMin: 4200, autoDropRange: 4500,\n      autoPokeMin: 450, autoPokeRange: 350,\n      hoverPoke: 50, clickPoke: 900,\n      gridW: 180, gridH: 110,\n    });\n    // Mount on the final CTA (purple surface \u2014 #5150f7)\n    mountFluidRipples(document.getElementById('finalCanvas'), {\n      baseR: 81, baseG: 80, baseB: 247,\n      shade: 0.085, // tuned for saturated purple\n    });\n  }\n";

function parseApiError(payload: ApiErrorPayload | null): string | null {
  if (!payload) return null;
  if (typeof payload.error === "string") return payload.error;
  if (payload.error && typeof payload.error === "object" && typeof payload.error.message === "string") return payload.error.message;
  if (typeof payload.message === "string") return payload.message;
  return null;
}

async function startCheckout(packageCode: PackageCode, link: HTMLAnchorElement) {
  const mappedPriceId = PACKAGE_TO_PRICE_ID[packageCode];
  const original = link.textContent ?? "Choose package";
  const existingError = link.parentElement?.querySelector(".lf-static-checkout-error");
  existingError?.remove();

  if (isPlaceholderPriceId(mappedPriceId)) {
    link.insertAdjacentHTML("afterend", '<p class="lf-static-checkout-error">Checkout is temporarily unavailable for this package. Please contact support.</p>');
    return;
  }

  link.setAttribute("aria-disabled", "true");
  link.textContent = "Redirecting…";

  try {
    const res = await fetch("/api/checkout/session", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ package_code: packageCode }),
    });

    const isJson = res.headers.get("content-type")?.includes("application/json");
    const data = isJson ? ((await res.json().catch(() => null)) as ApiErrorPayload | null) : null;

    if (!res.ok) throw new Error(parseApiError(data) ?? `Unable to start checkout (HTTP ${res.status})`);
    if (!data?.url) throw new Error("Checkout session was created without a redirect URL. Please contact support.");

    window.location.assign(data.url);
  } catch (error) {
    link.removeAttribute("aria-disabled");
    link.textContent = original;
    const message = error instanceof Error ? error.message : "Unable to start checkout";
    link.insertAdjacentHTML("afterend", `<p class="lf-static-checkout-error">${message}</p>`);
  }
}

export function StaticLandingPageV2() {
  useEffect(() => {
    const controller = new AbortController();
    document.querySelectorAll<HTMLAnchorElement>("a.pkg-cta[data-package]").forEach((link) => {
      link.addEventListener("click", (event) => {
        event.preventDefault();
        if (link.getAttribute("aria-disabled") === "true") return;
        const packageCode = link.dataset.package as PackageCode | undefined;
        if (packageCode) void startCheckout(packageCode, link);
      }, { signal: controller.signal });
    });

    try {
      new Function(rippleScript)();
    } catch (error) {
      console.warn("Logo Fountain landing animation failed", error);
    }

    return () => controller.abort();
  }, []);

  return (
    <>
      <style jsx global>{`${landingCss}
.lf-static-checkout-error{margin:12px 0 0;color:#b42318;font-size:13px;font-weight:700;line-height:1.35}
a.pkg-cta[aria-disabled="true"]{pointer-events:none;opacity:.7}`}</style>
      <div dangerouslySetInnerHTML={{ __html: landingHtml }} />
    </>
  );
}
